package com.afterglow.player;
import android.app.*;import android.os.*;import android.content.*;import java.io.*;
public class DownloadChecks extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}void check(boolean ok,String message){if(!ok)throw new AssertionError(message);android.util.Log.i("AfterglowDownloadTest","PASS: "+message);}
 public void onStart(){Bundle result=new Bundle();try{Intent intent=new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);MainActivity activity=(MainActivity)startActivitySync(intent);for(int n=0;n<50&&PlaybackService.instance==null;n++)Thread.sleep(100);AudioDownloader engine=new AudioDownloader(getTargetContext());String version=engine.version();check(!version.isEmpty(),"Packaged Python/yt-dlp runtime executes: "+version);result.putString("engine",version);PlaybackService s=PlaybackService.instance;int previous=s.index;int idx=s.queue.size();File old=AudioCache.find(getTargetContext(),"DTi8wZ1a1TA");if(old!=null&&!old.delete())throw new IOException("Cannot reset the test fixture");runOnMainSync(()->{s.queue.add(new Track("Downloader test fixture","Device check","DTi8wZ1a1TA","youtube"));activity.playTrack(idx);});for(int n=0;n<180;n++){Thread.sleep(1000);if(s.index==idx&&s.playing())break;if(n>3&&!DownloadService.busy&&!DownloadService.status.isEmpty()&&!DownloadService.status.startsWith("Cached"))break;}check(s.index==idx&&s.playing(),"Foreground download service completes and starts native playback: "+DownloadService.status);File file=AudioCache.find(getTargetContext(),"DTi8wZ1a1TA");check(file!=null&&file.exists()&&file.length()>0,"Public downloader test fixture cached");long size=file.length();File reused=new AudioDownloader(getTargetContext()).download("DTi8wZ1a1TA",message->{throw new AssertionError("Cached replay must not initialize network engine");});check(reused.equals(file)&&reused.length()==size,"Repeat uses completed cache without network");runOnMainSync(()->s.play(idx));for(int n=0;n<100&&!s.ready;n++)Thread.sleep(100);runOnMainSync(()->{});check(s.playing(),"Cached YouTube audio plays through native MediaPlayer");check(s.dsp!=null,"Cached audio has native EQ processing");Thread.sleep(800);check(s.position()>0,"Cached playback position advances");runOnMainSync(()->{s.pause(true);s.releasePlayer();s.queue.remove(idx);s.index=Math.min(previous,s.queue.size()-1);s.save();activity.render();});result.putString("result","PASS: native extractor, real network audio download, cache reuse, native playback and EQ");finish(Activity.RESULT_OK,result);}catch(Throwable e){android.util.Log.e("AfterglowDownloadTest","FAIL",e);result.putString("failure",e.toString());result.putString("diagnostic",AudioDownloader.diagnostic);finish(Activity.RESULT_CANCELED,result);}}
}


